from itertools import combinations

class Solution:
    def supersequences(self, words):
        present = 0
        forced = 0
        inadj = [0] * 26   # inadj[y] = bitmask of letters x with a word "xy" (x != y)
        for w in words:
            a = ord(w[0]) - 97
            b = ord(w[1]) - 97
            present |= (1 << a) | (1 << b)
            if a == b:
                forced |= 1 << a
            else:
                inadj[b] |= 1 << a

        free = [i for i in range(26) if (present >> i) & 1 and not (forced >> i) & 1]

        def acyclic(rem):
            # Kahn's algorithm on the letters in rem
            while rem:
                progress = False
                t = rem
                while t:
                    lb = t & -t
                    t ^= lb
                    u = lb.bit_length() - 1
                    if inadj[u] & rem == 0:
                        rem ^= lb
                        progress = True
                if not progress:
                    return False
            return True

        chosen = []
        for r in range(len(free) + 1):
            for comb in combinations(free, r):
                sub = forced
                for i in comb:
                    sub |= 1 << i
                if acyclic(present & ~sub):
                    chosen.append(sub)
            if chosen:
                break

        ans = []
        for sub in chosen:
            f = [0] * 26
            for i in range(26):
                if (present >> i) & 1:
                    f[i] = 2 if (sub >> i) & 1 else 1
            ans.append(f)
        return ans
